    NSLog(@"Button with ID %ld was clicked!", (long)self.BedID);
}
-(void)AddMethod{
    UITapGestureRecognizer *tapGestureRecognizer = [[UITapGestureRecognizer alloc]initWithTarget:self action:@selector(showMenu:)];
    [self addGestureRecognizer:tapGestureRecognizer];
}
- (void)initImages{
    if(!Initialized){
        Initialized = YES;
        
        SleepingBag = [UIImage imageWithData:[[NSData alloc] initWithBase64EncodedString:SleepingBagImage options:0]];
        SimpleBed = [UIImage imageWithData:[[NSData alloc] initWithBase64EncodedString:SimpleBedImage options:0]];
        BunkBed = [UIImage imageWithData:[[NSData alloc] initWithBase64EncodedString:BunkBedImage options:0]];
        ElegantBed = [UIImage imageWithData:[[NSData alloc] initWithBase64EncodedString:ElegantBedImage options:0]];
        SleepingPod = [UIImage imageWithData:[[NSData alloc] initWithBase64EncodedString:SleepingPodImage options:0]];
        
        
    }
}
- (void)SetSleepingBag{
    [self initImages];
    [self setBackgroundImage:SleepingBag forState:UIControlStateNormal];
}
- (void)SetSimpleBed{
    [self initImages];
    [self setBackgroundImage:SimpleBed forState:UIControlStateNormal];
}
- (void)SetElegantBed{
    [self initImages];
    [self setBackgroundImage:ElegantBed forState:UIControlStateNormal];
}
- (void)SetBunkBed{
    [self initImages];
    [self setBackgroundImage:BunkBed forState:UIControlStateNormal];
}
- (void)SetSleepingPod{
    [self initImages];
    [self setBackgroundImage:SleepingPod forState:UIControlStateNormal];
}

