static void (*ServerTransferAllToRemoteInventory)(long AShooterPlayerController, long PrimalInventoryComponent, FString* FolderFilter, FString* NameFilter, FInventoryFilter CurrentFilter) = (void(*)(long,long,FString*,FString*,FInventoryFilter))utils.getOffset(0x10cb6e8);
static void (*ServerTransferAllFromRemoteInventory)(long AShooterPlayerController, long PrimalInventoryComponent, FString* FolderFilter, FString* NameFilter, FInventoryFilter CurrentFilter) = (void(*)(long,long,FString*,FString*,FInventoryFilter))utils.getOffset(0x10cb524);
static void (*ServerMultiUse)(long AShooterPlayerController, long Object, int UseIndex, int ComponentIndex, bool bAllowSpam, bool ignoreDisableUse) = (void(*)(long, long , int , int , bool , bool))utils.getOffset(0x10c9108);
 
static NSString* StealString = @"";
static NSString* TransferString = @"";


static UIImage* TransferImage;
static UIImage* StealImage;


static bool TransferInitialized = false;
static bool StealInitialized = false;

@interface TransferButton ()
@end

@implementation TransferButton
- (void)AddMethod{
    if(!TransferInitialized){
        TransferInitialized = YES;
        TransferImage = [UIImage imageWithData:[[NSData alloc] initWithBase64EncodedString:TransferString options:0]];
    }
    
    [self setBackgroundImage:TransferImage forState:UIControlStateNormal];
    
    UITapGestureRecognizer *tapGestureRecognizer = [[UITapGestureRecognizer alloc]initWithTarget:self action:@selector(TransferItems:)];
    [self addGestureRecognizer:tapGestureRecognizer];
}
-(void)TransferItems:(UITapGestureRecognizer *)tapGestureRecognizer {
    if(tapGestureRecognizer.state == UIGestureRecognizerStateEnded) {
        
        UObject* Object = self.Pointer;
        
        long MyPrimalInventoryComponent = utils.Read<long>(Object + 0xbe8);
        if(!utils.isValidAdress(MyPrimalInventoryComponent)){
            MyPrimalInventoryComponent = utils.Read<long>(Object + 0x1de8);
        }
        
        if(utils.isValidAdress(MyPrimalInventoryComponent))
            functions.TransferItems((UObject*)MyPrimalInventoryComponent);
    }
}
-(void)move:(float)x y:(float)y{
    self.frame = CGRectMake(x, y-25, 25, 25);
}
@end





